// Probe the stronger lattice condition only; failure is not a source counterexample.
#include <bits/stdc++.h>
using namespace std;using ll=long long;using I=__int128_t;
string dec(I x){if(!x)return"0";bool neg=x<0;if(neg)x=-x;string s;while(x){s+=char('0'+x%10);x/=10;}if(neg)s+='-';reverse(s.begin(),s.end());return s;}
int main(){mt19937 R(43003338);long long cases=0;for(int q:{3,4,5}){int Q=q*q*q*q;vector<array<unsigned char,16>>f(Q);vector<int>zero(Q);for(int k=0;k<Q;k++){int x=k,c[4];for(int i=0;i<4;i++){c[i]=x%q;x/=q;if(!c[i])zero[k]|=1<<i;}for(int S=0;S<16;S++){int seen=0;for(int i=0;i<4;i++)if(S>>i&1)seen|=1<<c[i];f[k][S]=q-__builtin_popcount((unsigned)seen);}}
for(int trial=0;trial<50000;trial++){int m=2+R()%17;vector<int>nb;for(int j=0;j<m;j++){int mask;do{mask=1+R()%15;}while(__builtin_popcount((unsigned)mask)<2);nb.push_back(mask);}ll w[16]={};for(int k=0;k<Q;k++){ll z=1;for(int S:nb){z*=f[k][S];if(!z)break;}w[zero[k]]+=z;}cases++;for(int i=0;i<4;i++)for(int j=i+1;j<4;j++)for(int S=0;S<16;S++)if(!(S>>i&1)&&!(S>>j&1)){I d=I(w[S])*w[S|(1<<i)|(1<<j)]-I(w[S|(1<<i)])*w[S|(1<<j)];if(d<0){cout<<"{\"status\":\"STRONGER_LATTICE_FAILURE_ONLY\",\"q\":"<<q<<",\"cases\":"<<cases<<",\"neighborhoods\":[";for(size_t z=0;z<nb.size();z++){if(z)cout<<',';cout<<nb[z];}cout<<"],\"base_zero_set\":"<<S<<",\"i\":"<<i<<",\"j\":"<<j<<",\"lattice_gap\":\""<<dec(d)<<"\",\"weights\":[";for(int s=0;s<16;s++){if(s)cout<<',';cout<<w[s];}cout<<"]}\n";return 0;}}}}
cout<<"{\"status\":\"NO_LATTICE_FAILURE_IN_FINITE_PROBE\",\"cases\":"<<cases<<",\"seed\":43003338,\"scope\":\"A size4, q3-5, repeated B neighborhoods, finite diagnostic only\"}\n";}
